mapper.select:
 select r.riskid,r.risknumber,r.riskname,o.orgname as UNIT,r.riskcreatedt,r.version,r.riskdes,trc.riskcopingid,trc.status from tbl_risk r  
             left join tbl_organization o on r.unit = to_char(o.orgid) 
             left join TBL_RISK_COPING trc on trc.riskid = r.riskid  
             where  1=1

	  and  r.riskid   in (select max(riskid) as riskcreatedt from tbl_risk where riskcatid in  

	     #{item}

	     group by risknumber) 



    and risknumber  LIKE
			concat(concat('%',#{queryParam.risknumber}),'%')



    and riskname  LIKE
			concat(concat('%',#{queryParam.riskname}),'%')



    and unit =#{queryParam.unit}



    and status=#{queryParam.status}



    and level  not in ('未评估')



    and  r.STAFFID=#{queryParam.staffid}



	and riskcreatedt >=#{queryParam.startdate}


	and riskcreatedt <=#{queryParam.enddate}

order by RISKCREATEDT desc
